package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

import static org.junit.Assert.assertEquals;;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // offset 0, length 7. Ends with space.
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   0755 ".getBytes();
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, 8));
    }

    @Test
    public void testParseOctal_ValidWithTrailingNUL() {
        byte[] buffer = "000777\0".getBytes();
        assertEquals(511L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithMixedTrailing() {
        byte[] buffer = "00010 \0 ".getBytes();
        assertEquals(8L, TarUtils.parseOctal(buffer, 0, 8));
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buffer = new byte[]{0, 0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test
    public void testParseOctal_OffsetTest() {
        byte[] buffer = "abc 0123 \0".getBytes();
        // Start at index 4, length 7 (includes space and NUL)
        assertEquals(11L, TarUtils.parseOctal(buffer, 4, 7));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailingChar() {
        // Last char is '9', which is not 0 or ' '
        byte[] buffer = "01239".getBytes();
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        // '8' is not a valid octal digit
        byte[] buffer = "0128 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] buffer = "012A ".getBytes();
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max octal for long (approx)
        byte[] buffer = "777777777777777777 ".getBytes();
        long expected = Long.parseLong("777777777777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_MinimumLengthTwo() {
        byte[] buffer = "0 ".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 2));
    }

    @Test
    public void testParseOctal_TrailingNULAndSpaceCombined() {
        byte[] buffer = "012 \0 ".getBytes();
        // end-1 is space, end becomes end-1.
        // trailer becomes \0, loop continues.
        // end becomes end-1.
        // trailer becomes ' ', loop continues.
        // loop terminates because start < end-1 is false or trailer check.
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, 6));
    }
}
